CREATE POLICY "Anyone can read profile avatars" ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'profile-avatars');
CREATE POLICY "Users upload own profile avatars" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'profile-avatars' AND (storage.foldername(name))[1] = auth.uid()::text AND lower(storage.extension(name)) IN ('jpg','jpeg','png','webp'));
CREATE POLICY "Users update own profile avatars" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'profile-avatars' AND ((storage.foldername(name))[1] = auth.uid()::text OR public.has_role(auth.uid(), 'admin'))) WITH CHECK (bucket_id = 'profile-avatars' AND ((storage.foldername(name))[1] = auth.uid()::text OR public.has_role(auth.uid(), 'admin')));
CREATE POLICY "Users delete own profile avatars" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'profile-avatars' AND ((storage.foldername(name))[1] = auth.uid()::text OR public.has_role(auth.uid(), 'admin')));